-- UTF-8; SQLite / Cloudflare D1 compatible; idempotent; non-destructive.
-- UN Parallel Corpus v1.0. Source acknowledgement is mandatory.
CREATE TABLE IF NOT EXISTS un_parallel_zhfr (
  record_id TEXT PRIMARY KEY NOT NULL,
  dataset TEXT NOT NULL CHECK (dataset IN ('test','dev')),
  source_line INTEGER NOT NULL,
  document_path_raw TEXT NOT NULL,
  zh_alignment_raw TEXT NOT NULL,
  fr_alignment_raw TEXT NOT NULL,
  full_alignment_raw TEXT NOT NULL,
  text_zh TEXT NOT NULL,
  text_fr TEXT NOT NULL,
  content_pair_sha256 TEXT NOT NULL,
  translation_provenance TEXT NOT NULL,
  alignment_review_status TEXT NOT NULL,
  teaching_review_status TEXT NOT NULL DEFAULT 'not_reviewed',
  source_name TEXT NOT NULL,
  source_url TEXT NOT NULL,
  citation TEXT NOT NULL,
  UNIQUE(dataset,source_line)
);
CREATE INDEX IF NOT EXISTS idx_un_zhfr_doc ON un_parallel_zhfr(document_path_raw);
CREATE INDEX IF NOT EXISTS idx_un_zhfr_split ON un_parallel_zhfr(dataset);
CREATE INDEX IF NOT EXISTS idx_un_zhfr_review ON un_parallel_zhfr(teaching_review_status);
CREATE INDEX IF NOT EXISTS idx_un_zhfr_hash ON un_parallel_zhfr(content_pair_sha256);

INSERT OR IGNORE INTO un_parallel_zhfr (record_id, dataset, source_line, document_path_raw, zh_alignment_raw, fr_alignment_raw, full_alignment_raw, text_zh, text_fr, content_pair_sha256, translation_provenance, alignment_review_status, teaching_review_status, source_name, source_url, citation) VALUES
('UNV1_TEST_00004', 'test', 4, '2015/a/69/l_63', 'zh:60:1', 'fr:64:1', '2015/a/69/l_63 ar:58:1 en:61:1 es:58:1 fr:64:1 ru:61:1 zh:60:1', '31. 确认非洲同行审议机制自成立以来在非洲国家改进治理和支持社会经济发展方面所作的重要贡献，并在这方面回顾大会第六十八届会议期间于2013年10月21日为纪念该机制成立十周年举办的关于非洲通过非洲同行审议机制十年开展的治理创新的高级别小组讨论；', '31. Apprécie l''importante contribution que le Mécanisme africain d''évaluation par les pairs apporte depuis sa création à l''amélioration de la gouvernance et à l''appui au développement socioéconomique dans les pays d''Afrique, et rappelle à cet égard la table ronde de haut niveau organisée le 21 octobre 2013 pendant sa soixante-huitième session, sur le thème << L''innovation en matière de gouvernance en Afrique depuis la mise en place du Mécanisme africain d''évaluation par les pairs il y a 10 ans >>, à l''occasion du dixième anniversaire du Mécanisme;', 'd423ac6c2cbdc172f4ff400e8373a6787f14daa8dd4b71be8446479fdfc6bcf0', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00007', 'test', 7, '2015/s/agenda/7423', 'zh:2:1', 'fr:2:1', '2015/s/agenda/7423 ar:2:1 en:2:1 es:2:1 fr:2:1 ru:3:1 zh:2:1', '定于2015年4月2日星期四上午10时15分举行', 'Qui se tiendra le jeudi 2 avril 2015, à 10 h 15', '3c1be97d0c61a165eb31803cf538f54f009076b1ca84a3c7dd3a4deddd16c2bb', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00029', 'test', 29, '2015/s/2015/185', 'zh:2:1', 'fr:4:1', '2015/s/2015/185 ar:2:1 en:3:1 es:2:1 fr:4:1 ru:2:1 zh:2:1', '依照安全理事会暂行议事规则第15条的规定，秘书长谨报告，他收到俄罗斯联邦常驻联合国代表2015年3月16日来信，内称奥尔加·弗拉基米罗夫纳·莫佐莉娜女士和叶戈尔·谢尔盖耶维奇·舒利金先生已被任命为俄罗斯联邦出席安全理事会的候补代表。', 'Conformément à l''article 15 du Règlement intérieur provisoire du Conseil de sécurité, le Secrétaire général annonce qu''il a reçu du Représentant permanent de la Fédération de Russie auprès de l''Organisation des Nations Unies des lettres datées du 16 mars 2015 indiquant que Mme Olga Vladimirovna Mozolina et M. Egor Sergeevich Shulgin ont été nommés représentants suppléants de la Fédération de Russie au Conseil de sécurité.', '1c87d36916375f1cf9838e7df989e256af1f96f201e8c43c6583aa12655f98c9', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00031', 'test', 31, '2015/s/agenda/7441', 'zh:2:1', 'fr:2:1', '2015/s/agenda/7441 ar:2:1 en:2:1 es:2:1 fr:2:1 ru:3:1 zh:2:1', '定于2015年5月12日星期二下午3时举行', 'Qui se tiendra le mardi 12 mai 2015, à 15 heures', '68046e50dd3d9eb1f0703dfcfd1ce6be821b9ec84e2526243852257b01543066', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00037', 'test', 37, '2015/s/2015/334', 'zh:9:1', 'fr:13:1', '2015/s/2015/334 ar:11:1 en:9:1 es:10:1 fr:13:1 ru:14:1 zh:9:1', '新闻谈话', 'Déclaration à la presse', '5210b770ce8707be80b62a600c84a6e22846d158098cf9e877717db1c4a9cd09', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00044', 'test', 44, '2015/e/icef/2015/4', 'zh:64:1', 'fr:77:1', '2015/e/icef/2015/4 ar:63:1 en:63:1 es:63:1 fr:77:1 ru:67:1 zh:64:1', '中欧和东欧及独立国家联合体', 'Europe centrale et orientale et Communauté d''États indépendants', '66062a04961c47573cfe9f495ddc7886fa4fff6b3e529b5565f6f55f2ccdd1bc', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00051', 'test', 51, '2015/a/69/251/add_1', 'zh:3:1', 'fr:4:1', '2015/a/69/251/add_1 ar:3:1 en:3:1 es:3:1 fr:4:1 ru:3:1 zh:3:1', '增编', 'Additif', '42cb2cfc42f7e017f7c80f7e85e49cfbdc512aecd1911505ecd21c531f3d8bc8', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00088', 'test', 88, '2015/s/2015/326', 'zh:2:1', 'fr:4:1', '2015/s/2015/326 ar:2:1 en:2:1 es:2:1 fr:4:1 ru:2:1 zh:2:1', '依照安全理事会暂行议事规则第15条的规定，秘书长谨报告，他收到新西兰外交部长2015年5月8日签署的全权证书，内称杰拉德斯·雅各布斯·范博希曼先生已被任命为新西兰出席安全理事会的代表。', 'Conformément à l''article 15 du règlement intérieur provisoire du Conseil de sécurité, le Secrétaire général annonce qu''il a reçu des pouvoirs, signés le 8 mai 2015 par le Ministre des affaires étrangères de la Nouvelle-Zélande, attestant que M. Gerardus Jacobus van Bohemen a été nommé représentant de la Nouvelle-Zélande au Conseil de sécurité.', '8061526f1ceb25da5621545811eee5a262c23477d8d52aea1afb4f8cac73ee10', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00091', 'test', 91, '2015/s_/2015/369', 'zh:3:1', 'fr:6:1', '2015/s_/2015/369 ar:3:1 en:3:1 es:2:1 fr:6:1 ru:2:1 zh:3:1', '我于2015年5月2日至5日以建设和平委员会中非共和国组合主席的身份访问了班吉。', 'En ma qualité de Président de la formation République centrafricaine de la Commission de consolidation de la paix, je me suis rendu à Bangui du 2 au 5 mai 2015.', '16933b36b2dcd481e49b90dfabf40a04a4cabe91f37ce0d834d705377e0ab7fe', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_00104', 'test', 104, '2015/s/2015/398', 'zh:1:1', 'fr:1:1', '2015/s/2015/398 ar:1:1 en:1:1 es:1:1 fr:1:1 ru:1:1 zh:1:1', '秘书长关于智利出席安全理事会会议代表全权证书的报告', 'Rapport du Secrétaire général concernant les pouvoirs du représentant du Chili au Conseil de sécurité', '0b851e2b7a95d58090b2ce74194c60d57c3bdee4663f3529a2c952f9900a24e1', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.');
