('UNV1_TEST_01418', 'test', 1418, '2015/a/70/6__sect__3_', 'zh:484:2', 'fr:477:2', '2015/a/70/6__sect__3_ ar:496:2 en:459:2 es:468:2 fr:477:2 ru:520:2 zh:484:2', '建设和平支助办公室协助建设和平委员会在各实质性方面开展工作，并代表秘书长管理建设和平基金。', 'Le Bureau d''appui à la consolidation de la paix apporte son concours à la Commission de consolidation de la paix sur le plan technique et assure le bon fonctionnement du Fonds pour la consolidation de la paix, par délégation du Secrétaire général.', '7280772adee96d48cbc278e0fc1df8e60adc28112f9bfe435e13939f3108f1ae', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01439', 'test', 1439, '2015/e/2015/67', 'zh:3:1', 'fr:3:1', '2015/e/2015/67 ar:3:1 en:3:1 es:3:1 fr:3:1 ru:3:1 zh:3:1', '议程项目19(a)', 'Point 19 a) de l''ordre du jour', '54765912e50aed339016743526b364cadd9ec2a098dced2fd77db6e705022dd1', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
