('UNV1_TEST_01465', 'test', 1465, '2015/cac/cosp/irg/2015/2', 'zh:15:3', 'fr:16:3', '2015/cac/cosp/irg/2015/2 ar:17:2 en:21:3 es:17:4 fr:16:3 ru:16:3 zh:15:3', '有32个国家已经或将要进行最多三次审议。', 'Trente-deux États ont effectué ou auront effectué le nombre maximum d''examens, c''est-à-dire trois.', '94b9ed4b126c178deff50ecfc69b723c6365149111a0dd713aabe4d117181e46', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01466', 'test', 1466, '2015/s/ac_56/2015/4', 'zh:4:1', 'fr:6:1', '2015/s/ac_56/2015/4 ar:3:1 en:3:1 es:3:1 fr:6:1 ru:4:1 zh:4:1', '爱沙尼亚常驻联合国代表团向安全理事会第2140(2014)号决议所设委员会主席致意，并谨提及2015年3月11日的普通照会。', 'La Mission permanente de l''Estonie auprès de l''Organisation des Nations Unies présente ses compliments à la Présidente du Comité du Conseil de sécurité créé par la résolution 2140 (2014) et a l''honneur de se référer à la note verbale datée du 11 mars 2015.', 'd190239fa093f31acef5198220f1d7f51bb744f65e1104d2eaeab4dbc427003b', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01504', 'test', 1504, '2015/s/2015/355', 'zh:3:1', 'fr:5:1', '2015/s/2015/355 ar:3:1 en:3:1 es:3:1 fr:5:1 ru:3:1 zh:3:1', '请将本信及其附件分发给尊敬的安全理事会成员为荷，并作为安理会的文件。', 'Je vous serais reconnaissant de bien vouloir faire distribuer le texte de la présente lettre et son annexe aux membres du Conseil de sécurité et de la faire publier comme document du Conseil.', 'a798158b21540f2a6dfef3c9411cf3d37b40787b5b688e3092dc7f39bed90c20', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01572', 'test', 1572, '2015/a/70/6__sect__26_', 'zh:129:1', 'fr:119:1', '2015/a/70/6__sect__26_ ar:118:1 en:122:1 es:131:1 fr:119:1 ru:139:1 zh:129:1', '保持至少获得4次产前护理访问的妇女百分比', 'Maintien du pourcentage de femmes bénéficiant d''au moins 4 consultations prénatales', '7aaf8267e05ca4047695043442e2f3ef03ec0c425ebbc1b1e74f8b7c0a177f70', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01584', 'test', 1584, '2015/hsp/gc/25/5/add_2', 'zh:120:2', 'fr:126:2', '2015/hsp/gc/25/5/add_2 ar:118:2 en:120:2 es:118:2 fr:126:2 ru:118:2 zh:120:2', '在城市和气候变化倡议下，14个城市最终完成了气候变化脆弱性评估文件。', 'Selon l''Initiative sur les villes et les changements climatiques, 14 villes ont finalisé des documents d''évaluation de la vulnérabilité face aux changements climatiques.', 'a1df260e56cc7a1eb39b2f4812194602dd7da96d7e7de68fe8054bf9a1ae1d10', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01601', 'test', 1601, '2015/e/icef/2015/9', 'zh:103:1', 'fr:98:1', '2015/e/icef/2015/9 ar:99:1 en:101:1 es:96:1 fr:98:1 ru:103:1 zh:103:1', '2007-2014年财务披露方案合规率', 'Application du Dispositif de transparence financière, 2007-2014', 'b3c85b17a53c7f243fd1fa41b2d580d2af04ebced0e45fd60e5f1a953f6f5489', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01620', 'test', 1620, '2015/e/2015/52', 'zh:75:3', 'fr:85:3', '2015/e/2015/52 ar:73:3 en:73:3 es:73:3 fr:85:3 ru:79:3 zh:75:3', '这些改革加强了债券合约的合并条款，而基金组织将努力帮助各国把这些条款纳入它们今后的主权债务发行。', 'Les nouveaux contrats d''émission comportent des clauses d''agrégation plus strictes et le FMI aidera les pays à incorporer ces clauses dans leurs futures émissions de dette souveraine.', '5f2c805ecfbd09653e8134fdf644c9eaae1adc08a6ee4431bdb6cd70af61ad70', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.');
INSERT OR IGNORE INTO un_parallel_zhfr (record_id, dataset, source_line, document_path_raw, zh_alignment_raw, fr_alignment_raw, full_alignment_raw, text_zh, text_fr, content_pair_sha256, translation_provenance, alignment_review_status, teaching_review_status, source_name, source_url, citation) VALUES
('UNV1_TEST_01625', 'test', 1625, '2015/e/2015/44', 'zh:170:1', 'fr:192:1', '2015/e/2015/44 ar:164:1 en:170:1 es:166:1 fr:192:1 ru:171:1 zh:170:1', '52. 委员会认识到，可持续发展目标要求实现空前水平的政策整合。', 'Le Comité s''est déclaré conscient que les objectifs de développement durable appellent un degré d''intégration des politiques jusqu''ici inédit.', '4708119c46017dc6886817a7584434b91638aa5c2d34fa0c505a8c3be4160d34', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01628', 'test', 1628, '2015/a/cn_9/847', 'zh:63:1', 'fr:65:1', '2015/a/cn_9/847 ar:65:1 en:64:1 es:66:1 fr:65:1 ru:65:1 zh:63:1', '第11条 - 绝对优先强制性规则和公共政策（公共秩序）', 'Article 11 - Lois de police et ordre public', 'd02b65508a119b6d68abac909094ec6470ea839e4c908c9fd91735bb03589961', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01637', 'test', 1637, '2015/e/ac_51/2015/3', 'zh:75:2', 'fr:80:2', '2015/e/ac_51/2015/3 ar:76:2 en:77:2 es:78:2 fr:80:2 ru:78:2 zh:75:2', '监测和评价是否成功，取决于其能否在各适用领域提供必要信息，促进有依据的决策。', 'Elles sont exécutées avec succès lorsqu''elles permettent de prendre des décisions éclairées et fondées sur des données factuelles dans les divers domaines concernés.', '27faf86c7416e61f6e438c272cb381320478e9466557399fa5004e879aa40558', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01641', 'test', 1641, '2015/a/69/882', 'zh:13:1', 'fr:21:1', '2015/a/69/882 ar:14:1 en:13:1 es:13:1 fr:21:1 ru:21:1 zh:13:1', '在战争的黑暗年代，在战场上以及在后方，我们各国人民团结一致为共同的胜利而战斗，表现出了牢不可破的友谊和崇高的爱国主义精神。', 'Pendant les années sombres de la guerre, liés par une amitié indéfectible et mus par un patriotisme exemplaire, nos peuples ont combattu et travaillé pour construire ensemble la victoire commune.', '4e612ca571d6cefa2d4de877bf639202cbb2d84fd75b2c99b392c88e77662d37', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01677', 'test', 1677, '2015/clcs/l_39', 'zh:8:1', 'fr:8:1', '2015/clcs/l_39 ar:8:1 en:8:1 es:8:1 fr:8:1 ru:8:1 zh:8:1', '5. 委员会的工作量。', '5. Charge de travail de la Commission.', '40dd6629301c18b6aac44acca38d225e8fe77895ffa810f1358290054dbbc01b', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01697', 'test', 1697, '2015/a/69/291/add_2', 'zh:6:1', 'fr:7:1', '2015/a/69/291/add_2 ar:5:1 en:6:1 es:5:1 fr:7:1 ru:7:1 zh:6:1', '秘书长的说明', 'Note du Secrétaire général', '60ae4d2f6ad0674dd5a9f7d1e4dd362bfd9fb1dcd25878303eec5cbddf9b9e12', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01710', 'test', 1710, '2015/e/2015/l_10', 'zh:14:1', 'fr:16:1', '2015/e/2015/l_10 ar:14:1 en:14:1 es:15:1 fr:16:1 ru:16:1 zh:14:1', '3. 确认职员学院继续努力，在当前努力让联合国工作人员掌握应对全球挑战，包括执行2015年后发展议程所需的恰当知识和技能的背景下，巩固其在机构间学习、培训和知识共享方面发挥的核心作用；', '3. Prend acte des efforts que continue de déployer l''École des cadres pour renforcer le rôle central qu''elle joue dans les activités interinstitutions d''enseignement, de formation et de partage du savoir, compte tenu des mesures prises actuellement pour doter le personnel des Nations Unies des connaissances et compétences dont il a besoin pour faire face aux défis mondiaux, notamment la mise en œuvre du programme de développement pour l''après-2015;', '40e466c5e27d77d61af08549636374d9007c408b1affc57d02255de7a0aaeed5', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01723', 'test', 1723, '2015/e/2015/50', 'zh:224:1', 'fr:258:1', '2015/e/2015/50 ar:235:1 en:242:1 es:225:1 fr:258:1 ru:241:1 zh:224:1', '通过在执行符合全球协定的一致性国家政策方面加强协调，在抗击非传染疾病和急性病两方面都取得了进展。', 'Des progrès ont été accomplis dans la lutte contre les maladies non transmissibles et aiguës, grâce à une meilleure coordination de la mise en œuvre de politiques nationales cohérentes axées sur des accords mondiaux.', '0dcf4a6beb71e322616afb6ef421b86e58e906d3ec8c0be6701d2a117da60512', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01735', 'test', 1735, '2015/s/2015/274', 'zh:13:1', 'fr:14:1', '2015/s/2015/274 ar:12:1 en:12:1 es:12:1 fr:14:1 ru:14:1 zh:13:1', '外交与国际合作部对2005年和2010年大选产生的政府展现出落实《阿鲁沙协定》精神的意愿感到庆幸，并也确认2003年过渡政府与当时武装运动保卫民主全国委员会-保卫民主力量签署的《全面停火协定》对上述协定作了改进。', 'Le Ministère des relations extérieures et de la coopération internationale se félicite que le Gouvernement issu des élections générales de 2005 et de 2010 ait démontré la volonté de mettre en application l''esprit de l''Accord d''Arusha en reconnaissant, par ailleurs, qu''il a été amélioré par l''Accord global de cessez-le-feu signé en 2003 entre le Gouvernement de transition et le Conseil national pour la défense de la démocratie-Forces pour la défense de la démocratie, alors mouvement armé.', 'b472c3a51cd4a337b038c818e95afdd1647bf7a09f32cd4a6214351f0ee338e0', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.'),
('UNV1_TEST_01762', 'test', 1762, '2015/s/2015/292', 'zh:79:1', 'fr:87:1', '2015/s/2015/292 ar:81:1 en:83:1 es:82:1 fr:87:1 ru:84:1 zh:79:1', '第一次会议讨论了安理会工作中的一系列差距。', 'Les discussions qui ont eu lieu lors de la table ronde I ont mis en évidence un certain nombre de lacunes dans les travaux du Conseil.', 'b21e74ab0f171889f00d3610399359e1e2c12636c93c985bf0abd5f76d3c3168', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.');
