('UNV1_DEV_02575', 'dev', 2575, '2015/a/69/102/add_2', 'zh:5:1', 'fr:6:1', '2015/a/69/102/add_2 ar:4:1 en:5:1 es:4:1 fr:6:1 ru:5:1 zh:5:1', '任命会费委员会成员', 'Nomination de membres du Comité des contributions', '7efae510b157e27becdec580798edd24554c939b54a6e79bdb5c4696c1558014', 'UN_manually_translated_documents', 'source_alignment_not_independently_verified', 'not_reviewed', 'United Nations Parallel Corpus v1.0', 'https://conferences.unite.un.org/UNCorpus', 'Ziemski, M., Junczys-Dowmunt, M., and Pouliquen, B. (2016). The United Nations Parallel Corpus. LREC 2016.');
